Mutation = Callable[[Path, Path], None]


@dataclass
class Case:
    name: str
    expect: str | None            # check id that must appear; None = no blocking finding
    mutate: Mutation | None = None
    with_vision: bool = True
    scope: str = "full-stack"
    as_zip_slip: bool = False
    forbid: str | None = None     # check id that must NOT appear


def _sub(path: Path, old: str, new: str) -> None:
    text = path.read_text(encoding="utf-8")
    if old not in text:
        raise AssertionError(f"self-test fixture drifted: «{old[:40]}» not found in {path.name}")
    path.write_text(text.replace(old, new, 1), encoding="utf-8")


def _journey(ret: Path) -> Path:
    return ret / "FEAT-999" / "user_journey.md"


def _only_vision(_repo: Path, ret: Path) -> None:
    import shutil
    shutil.rmtree(ret / "FEAT-999")
    text = (ret / "MANIFEST.yaml").read_text(encoding="utf-8")
    head = text.split("features:", 1)[0]
    (ret / "MANIFEST.yaml").write_text(head + "features: []\n", encoding="utf-8")


def _strip_tokens(_repo: Path, ret: Path) -> None:
    for name in ("style_guide.html", "app_shell.html"):
        path = ret / "VISION" / name
        path.write_text(re.sub(r"<style>.*?</style>", "", path.read_text(encoding="utf-8"), flags=re.S),
                        encoding="utf-8")


def _new_component(_repo: Path, ret: Path) -> None:
    _sub(ret / "VISION" / "component_library.html", "</main>",
         '<section id="stepper" data-component="Stepper"><h2>Stepper</h2></section></main>')


