def _zip_slip(root: Path) -> Path:
    target = root / "slip.zip"
    with zipfile.ZipFile(target, "w") as archive:
        archive.writestr("MANIFEST.yaml", "features: []\n")
        archive.writestr("../escaped.txt", "out of the folder")
    return target


def _run_case(case: Case, grammar: Path, cfg: dict) -> str | None:
    """None when the case behaves; otherwise the reason it does not."""
    with tempfile.TemporaryDirectory(prefix="po-selftest-") as tmp:
        root = Path(tmp)
        repo = F.emit_repo(root, grammar)
        ret = F.emit_return(root, with_vision=case.with_vision, scope=case.scope)
        if case.mutate:
            case.mutate(repo, ret)
        rep = V.validate_zip(_zip_slip(root), repo, cfg) if case.as_zip_slip else V.validate_dir(ret, repo, cfg)
        if not case.as_zip_slip and (root / "escaped.txt").exists():
            return "a file was written outside the working folder"
    seen = {f.check for f in rep.findings}
    if case.forbid and case.forbid in seen:
        return f"«{case.forbid}» fired and must not"
    if case.expect is None:
        blocking = [f"{f.check}: {f.message}" for f in rep.blocking]
        return f"expected a clean return, got {blocking}" if blocking else None
    return None if case.expect in seen else f"«{case.expect}» did not fire (saw {sorted(seen) or 'nothing'})"


def _coverage_gaps() -> list[str]:
    source = Path(V.__file__).read_text(encoding="utf-8")
    literal = set(re.findall(r'rep\.add\(\s*"(?:BLOCKER|ERROR|WARN)",[^"]*?"([a-z][a-z0-9-]+)"', source, re.S))
    declared = set(V.ALL_CHECKS)
    covered = {c.expect for c in CASES if c.expect}
    gaps = [f"check «{c}» is used but not declared in ALL_CHECKS" for c in sorted(literal - declared)]
    gaps += [f"check «{c}» has no red case — a check that only sees green is decoration"
             for c in sorted(declared - covered)]
    return gaps


def run(grammar: Path) -> int:
    if not grammar.exists():
        print(f"SELFTEST CANNOT RUN: the journey gate is missing at {grammar}")
        return 2
    cfg = L.merge_config(L.DEFAULT_CONFIG, F.FIXTURE_CONFIG)
    failures = 0
    for case in CASES:
        reason = _run_case(case, grammar, cfg)
        failures += 1 if reason else 0
        print(f"  {'FAIL' if reason else 'ok  '}  {case.name}" + (f" — {reason}" if reason else ""))
    for gap in _coverage_gaps():
        failures += 1
        print(f"  FAIL  coverage — {gap}")
    print(f"\nselftest: {len(CASES)} cases, {failures} failure(s)")
    return 1 if failures else 0
